import math

def wrap(a):
    return (a+180.0)%360.0-180.0

state={'phase':'rev','g':None,'n':0,'woke':False}

def pts_from(view):
    ox,oy=view['origin']
    out=[]
    for b,d in view.get('walls',[]):
        r=math.radians(b)
        out.append((ox+d*math.cos(r),oy+d*math.sin(r)))
    return out

def corners_from(view):
    ox,oy=view['origin']
    out=[]
    try:
        for c in view.get('target_corners',[]) or []:
            b,d=c[0],c[1]
            r=math.radians(b)
            out.append((ox+d*math.cos(r),oy+d*math.sin(r)))
    except Exception:
        pass
    return out

def free_along(pts,ox,oy,th,hw):
    ux,uy=math.cos(math.radians(th)),math.sin(math.radians(th))
    f=9.0
    for x,y in pts:
        dx,dy=x-ox,y-oy
        al=dx*ux+dy*uy
        lat=abs(-dx*uy+dy*ux)
        if al>0 and lat<hw and al<f:
            f=al
    return f

def control(obs):
    st=state
    st['n']+=1
    hitch=obs['hitch_deg']
    rig=obs['rig']
    hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    tb=math.degrees(math.atan2(ry-hy,rx-hx))
    look=-23
    rem=obs['progress']['remaining']
    if st['phase']=='fwd':
        if abs(hitch)<8:
            st['phase']='rev'
        else:
            return (0.0,1.0,look)
    if abs(hitch)>40:
        st['phase']='fwd'
        return (0.0,1.0,look)
    cam=obs.get('views',{}).get('camera')
    fs=None
    if cam:
        pts=pts_from(cam)
        ox,oy=cam['origin']
        cs=corners_from(cam)
        if len(cs)>=2:
            cx=sum(p[0] for p in cs)/len(cs); cy=sum(p[1] for p in cs)/len(cs)
            st['g']=math.degrees(math.atan2(cy-oy,cx-ox))
        elif pts:
            best=-1;cands=[]
            for k in range(-20,21):
                th=tb+3*k
                f=free_along(pts,ox,oy,th,1.1)
                cands.append((th,f))
                best=max(best,f)
            good=[th for th,f in cands if f>=best-0.3]
            # circular mean around tb
            m=sum(wrap(th-tb) for th in good)/len(good)
            st['g']=tb+m
        else:
            st['g']=tb
        fs=free_along(pts,ox,oy,tb,0.9) if pts else 9.0
    g=st['g'] if st['g'] is not None else tb
    e_left=wrap(tb-g)
    hd=max(-25.0,min(25.0,0.8*e_left))
    steer=0.7*hd+2.0*(hitch-hd)
    steer=max(-34.0,min(34.0,steer))
    sp=-0.9
    if rem<6: sp=-0.5
    if fs is not None and fs<0.5:
        sp=0.0
        if not st['woke']:
            st['woke']=True
            wake('blocked behind, free %.2f'%fs)
    if st['n']%20==0:
        print('t%.1f h%.1f tb%.1f g%.1f hd%.1f st%.1f rem%.1f fs%s'%(obs['t'],hitch,tb,g,hd,steer,rem,fs))
    return (steer,sp,look)

