psi_f=0.0
phase='rev'
fwd_dist=0.0
look=150.0
look_t=None
tgt=None
last_prune=0.0
last_print=-10.0

def clamp(x,a,b):
    return a if x<a else (b if x>b else x)

def control(obs):
    global psi_f,phase,fwd_dist,look,look_t,tgt,last_prune,last_print
    t=obs.get('t',0.0); dt=obs.get('dt',0.1) or 0.1
    mo=obs.get('motion',{})
    v=mo.get('v_mps',0.0); st=obs.get('steer_deg',0.0)
    X,Y,yaw=pose
    yaw+=v*math.tan(math.radians(st))/2.5*dt
    X+=v*math.cos(yaw)*dt; Y+=v*math.sin(yaw)*dt
    pose[0]=X;pose[1]=Y;pose[2]=yaw
    c=math.cos(yaw); s=math.sin(yaw)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>18: continue
                x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
                wx=X+x*c-y*s; wy=Y+x*s+y*c
                M[(round(wx*4),round(wy*4))]=(wx,wy,t)
        except Exception:
            pass
    if t-last_prune>1.0:
        last_prune=t
        for k in [k for k,p in M.items() if t-p[2]>30]:
            del M[k]
    rig=obs.get('rig',{})
    tg=obs.get('target') or {}
    try:
        if tg.get('in_sight') and tg.get('bearing_deg') is not None:
            ex,ey=rig.get('eye',[0.75,0.0])
            b=math.radians(tg['bearing_deg']); d=tg['dist_m']
            x=ex+d*math.cos(b); y=ey+d*math.sin(b)
            tgt=(X+x*c-y*s, Y+x*s+y*c)
    except Exception:
        pass
    rx,ry=rig.get('trailer_rear',[-6.3,0.0])
    th=math.radians(rig.get('trailer_heading_deg',0.0))
    bu=(math.cos(th+math.pi),math.sin(th+math.pi))
    lw=(math.cos(th+math.pi/2),math.sin(th+math.pi/2))
