    for u,w in pts:
        if -4<u<2:
            if w>0: L=min(L,w)
            else: R=min(R,-w)
    psi_c=clamp(8.0*(L-R)/2.0,-10,10)
    best=0;bs=-1e9
    for ps in range(-45,46,5):
        cp=math.cos(math.radians(ps)); sp=math.sin(math.radians(ps))
        free=10.0
        for u,w in pts:
            u2=u*cp+w*sp; w2=-u*sp+w*cp
            if u2>0 and abs(w2)<1.6 and u2<free: free=u2
        sc=free-0.03*abs(ps-psi_f)-0.01*abs(ps)
        if sc>bs: bs=sc;best=ps
    psi_raw=best+psi_c
    rem=(obs.get('progress') or {}).get('remaining',99)
    if tgt is not None and rem<12:
        u,w=to_tr(tgt[0],tgt[1])
        if u>0.5:
            psi_raw=clamp(math.degrees(math.atan2(w,u)),-30,30)+0.3*psi_c
    psi_f+=0.3*(psi_raw-psi_f)
    h=obs.get('hitch_deg',0.0)
    status=obs.get('status','')
    if phase=='rev' and (abs(h)>42 or status=='JACKKNIFED'):
        phase='fwd'; fwd_dist=0.0
    if phase=='fwd':
        if v>0: fwd_dist+=v*dt
        steer=0.0; speed=0.8
        if (abs(h)<8 and fwd_dist>1.0) or fwd_dist>5.0:
            phase='rev'
    else:
        hd=clamp(1.0*psi_f,-25,25)
        steer=clamp(0.5*hd+2.5*(h-hd),-40,40)
        speed=-0.6
        if rem<8: speed=-0.45
        if abs(h-hd)>15: speed=-0.4
    head=obs.get('head',{})
    g=head.get('gaze_deg',0.0)
    if head.get('settled') and abs(g-look)<3:
        if look_t is None: look_t=t
        if t-look_t>1.0:
            look=-look; look_t=None
    if t-last_print>5:
        last_print=t
        print('t%.1f ph%s h%.1f psi%.1f best%d pc%.1f L%.1f R%.1f rem%.1f n%d tgt%s'%(t,phase,h,psi_f,best,psi_c,L,R,rem,len(pts),tgt is not None))
    return (steer,speed,look)

