import math
L=1.25;A=0.3;B=0.85
X=0.0;Y=0.0;TH=0.0
walls={}
corners=[]
C=None
mode='rev'
fstart=(0.0,0.0)
last_touch=0
head_side=1
head_t=0.0
last_print=-9.0
def wrap(a):
    return (a+180.0)%360.0-180.0
def clip(v,a,b):
    return max(a,min(b,v))
def tw(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return X+px*c-py*s,Y+px*s+py*c
def ray_free(qx,qy,ang,R,w,pts):
    c=math.cos(math.radians(ang));s=math.sin(math.radians(ang));free=R
    for (px,py) in pts:
        dx=px-qx;dy=py-qy;sp=dx*c+dy*s
        if sp<=0.05 or sp>=free: continue
        if abs(-dx*s+dy*c)<w: free=sp
    return free
def control(obs):
    global X,Y,TH,C,mode,fstart,last_touch,head_side,head_t,last_print
    dt=obs.get('dt',0.1) or 0.1
    t=obs.get('t',0.0)
    mo=obs['motion'];v=mo.get('v_mps',0.0) or 0.0
    st=math.radians(obs.get('steer_deg',0.0))
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt;TH+=v*math.tan(st)/L*dt
    views=obs.get('views') or {}
    for name in views:
        vw=views[name]
        if not vw: continue
        ox,oy=vw['origin']
        for w in (vw.get('walls') or []):
            try:
                b=math.radians(float(w[0]));d=float(w[1])
            except Exception:
                continue
            wx,wy=tw(ox+d*math.cos(b),oy+d*math.sin(b))
            walls[(round(wx/0.15),round(wy/0.15))]=(wx,wy)
        for cc in (vw.get('target_corners') or []):
            try:
                b=math.radians(float(cc[0]));d=float(cc[1])
            except Exception:
                continue
            wx,wy=tw(ox+d*math.cos(b),oy+d*math.sin(b))
            al=clip(1.5/max(d,0.1),0.1,0.6)
            best=None;bd=0.6
