            mode='fwd';fstart=(X,Y)
        else:
            mode='rev'
        wake('touch #%d, phi %.0f, mode %s'%(touches,phi,mode))
    if (mo.get('hold_s',0) or 0)>0:
        return (obs.get('steer_deg',0.0),0.0,look)
